// 1) Классический баг цикла: var одна на все итерации
for (var i = 0; i < 3; i++) setTimeout(() => console.log(i));   // 3 3 3
// чиним через let (новая ячейка на итерацию)…
for (let j = 0; j < 3; j++) setTimeout(() => console.log(j));   // 0 1 2
// …или через замыкание-IIFE (если где-то старый движок)
for (var k = 0; k < 3; k++) (function (x) { setTimeout(() => console.log(x)); })(k);

// 2) Замыкание: счётчик с приватным состоянием
const createCounter = (start = 0) => {
  let count = start;                       // живёт, пока жива функция-обёртка
  return { inc: () => ++count, get: () => count };
};
const c = createCounter(10);
c.inc(); c.inc(); c.get();                 // 12 — состояние недоступно снаружи

// 3) Ленивое замыкание: тяжёлые данные вычисляются один раз по требованию
const makeLoader = (fetchFn) => {
  let cached;                              // ячейка области видимости
  return async (force = false) => (cached && !force) ? cached : (cached = await fetchFn());
};

// 4) Утечка: замыкание в долгоживущем слушателе держит ВСЮ свою область
document.body.addEventListener('click', function handler() {
  const huge = new Array(1e6).fill('x');   // huge удерживается, пока жива ссылка на handler
});

class Timer {
  // Ловушка: метод, отданный колбэку, теряет this
  startBroken() { setTimeout(function () { this.secs += 1; }, 1000); }   // TypeError: this undefined

  // Решение 1: стрелка-поле — this берётся из экземпляра при создании
  startArrow = () => { this.secs = (this.secs ?? 0) + 1; setTimeout(() => { this.secs++; }, 1000); };

  // Решение 2: явная привязка в точке использования
  startBound() { setTimeout(this.tick.bind(this), 1000); }
  tick() { this.secs = (this.secs ?? 0) + 1; }
}

// Частичное применение через bind: типичный паттерн в реакт-подобных слоях
const send = (to, msg) => `${to}: ${msg}`;
const sendToAdmin = send.bind(null, 'admin');   // первый аргумент зафиксирован
sendToAdmin('deploy done');                     // "admin: deploy done"

// 1) Наследование через прототип (то, что делает class под капотом)
const Animal = { speak() { return `${this.name} makes a sound`; } };
const Dog = Object.create(Animal);                  // Dog.[[Prototype]] = Animal
Dog.bark = function () { return `${this.name} barks`; };
const rex = Object.create(Dog); rex.name = 'Rex';
rex.speak(); rex.bark();                            // "Rex makes a sound" / "Rex barks"
Object.getPrototypeOf(rex) === Dog;                 // true — цепочка видна глазами

// 2) class — синтаксический сахар + полезные отличия от «функций-конструкторов»
class Animal2 {
  kind = 'animal';                       // поле экземпляра (создаётся в конструкторе)
  static kingdom = 'Life';               // свойство класса, не экземпляра
  #secret = 42;                          // настоящая приватность (не «подчёркивание»)
  constructor(name) { this.name = name; }
  speak() { return `${this.name} makes a sound`; }       // лежит в prototype
  toString() { return `Animal2(${this.name})`; }
}
class Dog2 extends Animal2 {
  constructor(name) { super(name); }                 // super() обязателен до this
  speak() { return `${this.name} barks`; }            // переопределение метода прототипа
}
new Dog2('Rex').speak();                              // "Rex barks"
new Animal2('x') instanceof Animal2;                 // true — работает через цепочку prototype

// 3) Сравнение: приватность по-разному
class Api {
  #token = 't';                    // жёсткая: недоступна снаружи даже через Object.keys
  _legacy = 't';                   // «договорённость»: видна и удаляема
  #tokenRef = { value: 't' };      // вариант: слабые ссылки/замыкание для мутаций
}

// Композиция функций (правая/левая ассоциативность — как в точки)
const pipe = (...fns) => (x) => fns.reduce((acc, fn) => fn(acc), x);
const compose = (...fns) => (x) => fns.reduceRight((acc, fn) => fn(acc), x);
const fmt = pipe((s) => s.trim(), (s) => s.toLowerCase(), (s) => s.replace(/\s+/g, '-'));
fmt('  Hello   World  ');                     // "hello-world"

// Мемоизация (замыкание + Map): кэш живёт ровно пока живёт функция)
const memoize = (fn) => {
  const cache = new Map();
  return (...args) => {
    const key = JSON.stringify(args);
    if (cache.has(key)) return cache.get(key);
    const res = fn(...args);
    cache.set(key, res);
    return res;
  };
};

// Debounce: «выполни последний вызов через N мс тишины»
const debounce = (fn, ms) => {
  let t;
  return (...args) => { clearTimeout(t); t = setTimeout(() => fn(...args), ms); };
};

// Throttle: «не чаще, чем раз в N мс»
const throttle = (fn, ms) => {
  let last = 0;
  return (...args) => {
    const now = Date.now();
    if (now - last >= ms) { last = now; fn(...args); }
  };
};

console.log('A');                                   // стек, сразу
setTimeout(() => console.log('D'), 0);              // макрозадача (timers)
Promise.resolve().then(() => console.log('C'));     // микрозадача
queueMicrotask(() => console.log('B'));             // микрозадача, раньше промисов
// Порядок: A B C D

// await = приостановка + продолжение микрозадачей
async function f() {
  console.log(1);
  await Promise.resolve();                          // точка разрыва
  console.log(3);                                   // выполнится позже, чем…
}
f();
console.log(2);                                     // …эта строка: 1 2 3

// Таймаут + отмена сверху: одна «кнопка выключения» на все вложенные операции
async function fetchWithTimeout(url, { timeoutMs = 5_000, signal } = {}) {
  const ctrl = new AbortController();
  const onAbort = () => ctrl.abort(signal?.reason);
  signal?.addEventListener('abort', onAbort, { once: true });
  const timer = setTimeout(() => ctrl.abort(new Error('timeout')), timeoutMs);
  try {
    return await fetch(url, { signal: ctrl.signal });
  } finally {
    clearTimeout(timer);
    signal?.removeEventListener('abort', onAbort);
  }
}

// Гонка «старый ответ vs новые параметры» — чиним отменой и проверкой актуальности
let requestId = 0;
async function load(query) {
  const id = ++requestId;                       // метка актуальности
  const res = await search(query, { signal: ac.signal });
  if (id !== requestId) return;                 // ответ устарел — игнорируем
  render(res);
}

// Свой итератор — любая структура становится «дружелюбной» для for..of
function* range(start, end, step = 1) {           // генератор = ленивая фабрика итераторов
  for (let i = start; i < end; i += step) yield i;
}
[...range(0, 10, 2)];                             // [0, 2, 4, 6, 8]

// Итератор-обход «батчами по N» — типичное упражнение на интервью
function* batches(items, size) {
  for (let i = 0; i < items.length; i += size) {
    yield items.slice(i, i + size);
  }
}
for (const page of batches(Array.from({ length: 7 }, (_, i) => i), 3)) {
  console.log(page);                              // [0,1,2] [3,4,5] [6]
}

// Асинхронная итерация: работает с for await (стримы, курсоры БД, Kafka)
async function* latest(cursor) {
  while (cursor.hasNext()) yield await cursor.next();
}
for await (const row of latest(dbCursor)) handle(row);

// Группировка без циклов (reduce + Map)
const byStatus = [...orders.reduce((m, o) => {
  (m.get(o.status) ?? m.set(o.status, []).get(o.status)).push(o);
  return m;
}, new Map())];

class PaymentError extends Error {
  constructor(message, { code, paymentId, cause } = {}) {
    super(message, { cause });                    // cause — первопричина
    this.name = 'PaymentError';
    this.code = code ?? 'UNKNOWN';               // машинный код для клиента/логов
    this.paymentId = paymentId;
  }
}

async function charge(order) {
  try {
    await gateway.charge(order);
  } catch (err) {
    if (err instanceof PaymentError && err.code === 'CARD_DECLINED') {
      return { ok: false, reason: 'declined' };  // ожидаемый отказ — это не инцидент
    }
    throw new PaymentError('charge failed', { code: 'GATEWAY_ERROR', cause: err });
  }
}

// Подавление ошибки в finally — покажите коллеге и объясните, почему это плохо:
function bad() { try { throw new Error('x'); } finally { return 1; } }  // вернёт 1, ошибка потеряна

// Объект: значения по умолчанию, переименование, «хвост», вложенность
const { id, name: title = 'без имени', tags = [], ...profile } = user;
const { settings: { theme = 'light' } = {} } = user;   // безопасная вложенность с дефолтом

// Массив: пропуски, позиционные, «хвост»
const [first, , third = 3, ...rest] = [10, 20, 30, 40, 50];   // 10, 30, 30, [40, 50]

// Параметры функции — самая читаемая сигнатура
function createOrder({ customerId, items = [], comment } = {}) { /* ... */ }

// Spread объекта — ПОВЕРХНОСТНОЕ копирование!
const a = { meta: { v: 1 }, x: 1 };
const b = { ...a, x: 2 };          // b.meta === a.meta — общая ссылка на meta!
const deep = structuredClone(a);   // глубокая копия (не теряет Date/Map, в отличие от JSON-хака)

// ?? vs || : nullish-coalescing не подхватывает 0 и ''
const port = config.port ?? 3000;       // 0 останется 0
const port2 = config.port || 3000;      // 0 превратится в 3000 — сюрприз

// Опциональная цепочка — «проверь по пути», результат undefined
const city = user?.address?.city;
const len = user?.tags?.length;
user?.save?.();                                  // «если метод есть — вызови»

// Три способа «глубоко» — и их границы
JSON.stringify({ d: new Date(), u: undefined, m: new Map() });
// '{"d":"2026-01-01T00:00:00.000Z"}' — undefined и Map потеряны
structuredClone({ d: new Date(), u: undefined, m: new Map() });   // корректно (кроме функций)

// Детерминированное сравнение объектов для тестов
const stable = (v) => JSON.stringify(v, (_, x) =>
  x && typeof x === 'object' && !Array.isArray(x)
    ? Object.fromEntries(Object.entries(x).sort(([a], [b]) => a.localeCompare(b)))
    : x);
stable({ a: 1, b: { c: 2, d: 3 } }) === stable({ b: { d: 3, c: 2 }, a: 1 });   // true
